import{_ as t,o,c as r,a5 as p}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"SpringMVC 的入门","description":"","frontmatter":{"title":"SpringMVC 的入门","date":"2026-07-03T00:00:00.000Z","categories":["Java 快速入门"],"tags":["Java","Spring","OneNote"],"lastUpdated":false},"headers":[],"relativePath":"posts/java快速入门/第六部分：Spring 生态/03-Spring MVC/SpringMVC 的入门.md","filePath":"posts/java快速入门/第六部分：Spring 生态/03-Spring MVC/SpringMVC 的入门.md"}'),n={name:"posts/java快速入门/第六部分：Spring 生态/03-Spring MVC/SpringMVC 的入门.md"};function a(c,e,l,s,g,d){return o(),r("div",null,[...e[0]||(e[0]=[p('<div><p><strong>前期准备</strong><strong>下载开发包：</strong></p><p><a href="https://spring.io/projects" target="_blank" rel="noreferrer">https://spring.io/projects</a> 其实</p><p><code>spring mvc</code></p><p>的 <code>jar</code> 包就在之前我们的 <code>spring</code> 框架开发包中。</p><p><strong>创建一个</strong></p><ul><li>javaweb</li><li>jsp</li></ul><p>中的内容：</p><p>&lt;a href=&quot;${pageContext.request.contextPath}/hello&quot;&gt;SpringMVC 入门案例</p><ul><li>&lt;/a&gt;</li><li>&lt;br/&gt;</li><li>&lt;a href=&quot;hello&quot;&gt;SpringMVC</li></ul><p>入门案例</p><p><code>\\&lt;/a\\&gt;</code></p><p><strong>拷贝</strong> <code>jar</code> <strong>包</strong><code>spring mvc</code> 的 <code>jar</code> 包就在除了上面两个 <code>jar</code> 包之外，还需要拷贝 <code>spring</code> 的注解 <code>ioc</code> 所需 <code>jar</code> 包（包括一个 <code>aop</code> 的 <code>jar</code> 包）。</p><p>配置核心控制器<code>-</code>一个</p><p>Servlet &lt;?xml version=&quot;1.0&quot; encoding=&quot;UTF-8&quot;?&gt; &lt;web-app xmlns:xsi=&quot;<a href="http://www.w3.org/2001/XMLSchema-instance" target="_blank" rel="noreferrer">http://www.w3.org/2001/XMLSchema-instance</a>&quot; xmlns=&quot;<a href="http://java.sun.com/xml/ns/javaee" target="_blank" rel="noreferrer">http://java.sun.com/xml/ns/javaee</a>&quot; xsi:schemaLocation=&quot;<a href="http://java.sun.com/xml/ns/javaee" target="_blank" rel="noreferrer">http://java.sun.com/xml/ns/javaee</a><a href="http://java.sun.com/xml/ns/javaee/web-app_2_5.xsd" target="_blank" rel="noreferrer">http://java.sun.com/xml/ns/javaee/web-app_2_5.xsd</a>&quot; id=&quot;WebApp_ID&quot; version=&quot;2.5&quot;&gt; &lt;!-- 配置 <code>spring mvc</code> 的核心控制器</p><p>--&gt; &lt;servlet&gt; &lt;servlet-name&gt;SpringMVCDispatcherServlet&lt;/servlet-name&gt; &lt;servlet-class&gt; org.springframework.web.servlet.DispatcherServlet &lt;/servlet-class&gt; &lt;!-- 配置初始化参数，用于读取 <code>SpringMVC</code> 的配置文件</p><p>--&gt; &lt;init-param&gt; &lt;param-name&gt;contextConfigLocation&lt;/param-name&gt; &lt;param-value&gt;classpath:SpringMVC.xml&lt;/param-value&gt; &lt;/init-param&gt; &lt;!-- 配置 <code>servlet</code> 的对象的创建时间点：应用加载时创建。 取值只能是非</p><p><code>0</code></p><p>正整数，表示启动顺序</p><p>--&gt; &lt;load-on-startup&gt;1&lt;/load-on-startup&gt; &lt;/servlet&gt; &lt;servlet-mapping&gt; &lt;servlet-name&gt;SpringMVCDispatcherServlet&lt;/servlet-name&gt; &lt;url-pattern&gt;/&lt;/url-pattern&gt; &lt;/servlet-mapping&gt; &lt;/web-app&gt; <strong>创建</strong> <code>spring mvc</code> <strong>的配置文件</strong></p><p>&lt;?xml version=&quot;1.0&quot; encoding=&quot;UTF-8&quot;?&gt; &lt;beans xmlns=&quot;<a href="http://www.springframework.org/schema/beans" target="_blank" rel="noreferrer">http://www.springframework.org/schema/beans</a>&quot; xmlns:mvc=&quot;<a href="http://www.springframework.org/schema/mvc" target="_blank" rel="noreferrer">http://www.springframework.org/schema/mvc</a>&quot; xmlns:context=&quot;<a href="http://www.springframework.org/schema/context" target="_blank" rel="noreferrer">http://www.springframework.org/schema/context</a>&quot; xmlns:xsi=&quot;<a href="http://www.w3.org/2001/XMLSchema-instance" target="_blank" rel="noreferrer">http://www.w3.org/2001/XMLSchema-instance</a>&quot; xsi:schemaLocation=&quot;<a href="http://www.springframework.org/schema/beans" target="_blank" rel="noreferrer">http://www.springframework.org/schema/beans</a><a href="http://www.springframework.org/schema/beans/spring-beans.xsd" target="_blank" rel="noreferrer">http://www.springframework.org/schema/beans/spring-beans.xsd</a><a href="http://www.springframework.org/schema/mvc" target="_blank" rel="noreferrer">http://www.springframework.org/schema/mvc</a><a href="http://www.springframework.org/schema/mvc/spring-mvc.xsd" target="_blank" rel="noreferrer">http://www.springframework.org/schema/mvc/spring-mvc.xsd</a><a href="http://www.springframework.org/schema/context" target="_blank" rel="noreferrer">http://www.springframework.org/schema/context</a><a href="http://www.springframework.org/schema/context/spring-context.xsd" target="_blank" rel="noreferrer">http://www.springframework.org/schema/context/spring-context.xsd</a>&quot;&gt; &lt;!-- 配置创建 <code>spring</code> 容器要扫描的包</p><p>--&gt; &lt;context:component-scan base-package=&quot;com.itheima&quot;&gt;&lt;/context:component-scan&gt; &lt;!-- 配置视图解析器 <code>--\\&gt;</code> &lt;</p><p>bean class=&quot;org.springframework.web.servlet.view.InternalResourceViewResolver&quot;&gt; &lt;property name=&quot;prefix&quot; value=&quot;/WEB-INF/pages/&quot;&gt;&lt;/property&gt; &lt;property name=&quot;suffix&quot; value=&quot;.jsp&quot;&gt;&lt;/property&gt; &lt;/bean&gt; &lt;/beans&gt; <strong>编写控制器并使用注解配置</strong></p><p>/**</p><ul><li><p>spring mvc 的入门案例</p></li><li><p>@author 黑马程序员</p></li><li><p>@Company <a href="http://www.ithiema.com" target="_blank" rel="noreferrer">http://www.ithiema.com</a></p></li><li><p>@Version 1.0 */ @Controller(&quot;helloController&quot;) public class HelloController { @RequestMapping(&quot;/hello&quot;) public String sayHello() { System.out.println(&quot;HelloController 的 <code>sayHello</code> 方法执行了。。。。</p></li></ul><p>&quot;); return &quot;success&quot;; } } ￼ 测试</p><p><strong>入门案例的执行过程及原理分析</strong></p><p><strong>案例的执行过程</strong><code>1</code>、服务器启动，应用被加载。读取到 <code>web.xml</code> 中的配置创建 <code>spring</code> 容器并且初始化容器中的对象。从入门案例中可以看到的是：<code>HelloController</code> 和 <code>InternalResourceViewResolver</code>，但是远不 止这些。</p><p><code>2</code></p><p>、浏览器发送请求，被 <code>DispatherServlet</code> 捕获，该 <code>Servlet</code> 并不处理请求，而是把请求转发出去。转发的路径是根据请求 <code>URL</code>，匹配<code>@RequestMapping</code> 中的内容。 <code>3</code>、匹配到了后，执行对应方法。该方法有一个返回值。</p><p><code>4</code></p><p>、根据方法的返回值，借助 <code>InternalResourceViewResolver</code> 找到对应的结果视图。</p><p><code>5</code></p><p>、渲染结果视图，响应浏览器。</p><p><code>SpringMVC</code> <strong>的请求响应流程</strong></p><p><strong>入门案例中涉及的组件</strong><code>DispatcherServlet</code><strong>：前端控制器</strong> 用户请求到达前端控制器，它就相当于 <code>mvc</code> 模式中的 <code>c</code>，<code>dispatcherServlet</code> 是整个流程控制的中心，由它调用其它组件处理用户的请求，<code>dispatcherServlet</code> 的存在降低了组件之间的耦合性。</p><p><code>HandlerMapping</code><strong>：处理器映射器</strong><code>HandlerMapping</code> 负责根据用户请求找到 <code>Handler</code> 即处理器，<code>SpringMVC</code> 提供了不同的映射器实现不同的映射方式，例如：配置文件方式，实现接口方式，注解方式等。</p><p><code>Handler</code><strong>：处理器</strong> 它就是我们开发中要编写的具体业务控制器。由</p><p><code>DispatcherServlet</code></p><p>把用户请求转发到 <code>Handler</code>。由</p><p><code>Handler</code></p><p>对具体的用户请求进行处理。</p><p><code>HandlAdapter</code><strong>：处理器适配器</strong> 通过 <code>HandlerAdapter</code> 对处理器进行执行，这是适配器模式的应用，通过扩展适配器可以对更多类型的处理器进行执行。</p><p><code>View Resolver</code><strong>：视图解析器</strong><code>View Resolver</code> 负责将处理结果生成 <code>View</code> 视图，<code>View Resolver</code> 首先根据逻辑视图名解析成物理视图名即具体的页面地址，再生成 <code>View</code> 视图对象，最后对 <code>View</code> 进行渲染将处理结果通过页面展示给用户。</p><p><code>View</code><strong>：视图</strong><code>SpringMVC</code> 框架提供了很多的 <code>View</code> 视图类型的支持，包括：<code>jstlView</code>、<code>freemarkerView</code>、<code>pdfView</code> 等。我们最常用的视图就是</p><p><code>jsp</code></p><p>。 一般情况下需要通过页面标签或页面模版技术将模型数据通过页面展示给用户，需要由程序员根据业务需求开发具体的页面。</p><p><code>\\&lt;mvc:annotation-driven\\&gt;</code><strong>说明</strong> 在</p><p><code>SpringMVC</code></p><p>的各个组件中，处理器映射器、处理器适配器、视图解析器称为 <code>SpringMVC</code> 的三大组件。 使 用</p><p><code>\\&lt;mvc:annotation-driven\\&gt;</code></p><p>自动加载 <code>RequestMappingHandlerMapping</code> （处理映射器） 和</p><p><code>RequestMappingHandlerAdapter</code></p><p>（ 处 理 适 配 器 ） ， 可 用 在 <code>SpringMVC.xml</code> 配 置 文 件 中 使 用</p><p><code>\\&lt;mvc:annotation-driven\\&gt;</code></p><p>替代注解处理器和适配器的配置。 它就相当于在</p><p><code>xml</code></p><p>中配置了：</p><p><code>\\&lt;!--</code></p><p>上面的标签相当于 如下配置</p><p>--&gt; &lt;!-- Begin --&gt; &lt;!-- HandlerMapping --&gt; &lt;bean class=&quot;org.springframework.web.servlet.mvc.method.annotation.RequestMappingHandlerM apping&quot;&gt;&lt;/bean&gt; &lt;bean class=&quot;org.springframework.web.servlet.handler.BeanNameUrlHandlerMapping&quot;&gt;&lt;/bean&gt; &lt;!-- HandlerAdapter --&gt; &lt;bean class=&quot;org.springframework.web.servlet.mvc.method.annotation.RequestMappingHandlerA dapter&quot;&gt;&lt;/bean&gt; &lt;bean class=&quot;org.springframework.web.servlet.mvc.HttpRequestHandlerAdapter&quot;&gt;&lt;/bean&gt; &lt;bean class=&quot;org.springframework.web.servlet.mvc.SimpleControllerHandlerAdapter&quot;&gt;&lt;/bean&gt; &lt;!-- HadnlerExceptionResolvers --&gt; &lt;bean class=&quot;org.springframework.web.servlet.mvc.method.annotation.ExceptionHandlerExcept ionResolver&quot;&gt;&lt;/bean&gt; &lt;bean class=&quot;org.springframework.web.servlet.mvc.annotation.ResponseStatusExceptionResolv er&quot;&gt;&lt;/bean&gt; &lt;bean class=&quot;org.springframework.web.servlet.mvc.support.DefaultHandlerExceptionResolver&quot; &gt;&lt;/bean&gt; &lt;!-- End --&gt; <strong>注意：</strong><strong>一般开发中，我们都需要写上此标签（虽然从入门案例中看，我们不写也行，随着课程的深入，该标签还</strong><strong>有具体的使用场景）。</strong><strong>明确：</strong> 我们只需要编写处理具体业务的控制器以及视图。</p><p><code>RequestMapping</code> <strong>注解</strong><strong>使用说明</strong><strong>源码：</strong></p><p>@Target({ElementType.METHOD, ElementType.TYPE}) @Retention(RetentionPolicy.RUNTIME) @Documented @Mapping public @interface RequestMapping { } <strong>作用：</strong> 用于建立请求 <code>URL</code> 和处理请求方法之间的对应关系。 出现位置： 类上 请求</p><p><code>URL</code></p><p>的第一级访问目录。此处不写的话，就相当于应用的根目录。写的话需要以<code>/</code>开头。 它出现的目的是为了使我们的</p><p><code>URL</code></p><p>可以按照模块化管理<code>:</code> 例如： 账户模块：</p><ul><li>/account/add</li><li>/account/update</li><li>/account/delete</li><li>...</li></ul><p>订单模块：</p><ul><li>/order/add</li><li>/order/update</li><li>/order/delete</li></ul><p>红色的部分就是把</p><p><code>RequsetMappding</code></p><p>写在类上，使我们的 <code>URL</code> 更加精细。 方法上： 请求</p><p><code>URL</code></p><p>的第二级访问目录。 <strong>属性：</strong></p><p><code>value</code></p><p>：用于指定请求的 <code>URL</code>。它和 <code>path</code> 属性的作用是一样的。</p><p><code>method</code></p><p>：用于指定请求的方式。</p><p><code>params</code></p><p>：用于指定限制请求参数的条件。它支持简单的表达式。要求请求参数的 <code>key</code> 和 <code>value</code> 必须和 配置的一模一样。 例如：</p><p>params = {&quot;accountName&quot;} ，表示请求参数必须有</p><p>accountName params = {&quot;moeny!100&quot;} ，表示请求参数中 <code>money</code> 不能是 <code>100</code>。</p><p><code>headers</code></p><p>：用于指定限制请求消息头的条件。 注意： 以上四个属性只要出现</p><p><code>2</code></p><p>个或以上时，他们的关系是与的关系。</p><p><strong>使用示例</strong><strong>出现位置的示例：</strong><strong>控制器代码</strong></p><p>: /**</p><ul><li>RequestMapping 注解出现的位置</li></ul><p>*/ @Controller(&quot;accountController&quot;) @RequestMapping(&quot;/account&quot;) public class AccountController { ￼</p><p>public String findAccount() { System.out.println(&quot; 查询了账户。。。。</p><p>&quot;); return &quot;success&quot;; } }</p><p><code>jsp</code> <strong>中的代码：</strong></p><p>&lt;%@ page language=&quot;java&quot; contentType=&quot;text/html; charset=UTF-8&quot; pageEncoding=&quot;UTF-8&quot;%&gt; &lt;!DOCTYPE html PUBLIC &quot;-//W3C//DTD HTML 4.01 Transitional//EN&quot; &quot;<a href="http://www.w3.org/TR/html4/loose.dtd" target="_blank" rel="noreferrer">http://www.w3.org/TR/html4/loose.dtd</a>&quot;&gt; &lt;html&gt; &lt;head&gt; &lt;meta http-equiv=&quot;Content-Type&quot; content=&quot;text/html; charset=UTF-8&quot;&gt; &lt;title&gt;requestmapping 的使用</p><ul><li>&lt;/title&gt;</li><li>&lt;/head&gt;</li><li>&lt;body&gt;</li><li>&lt;!--</li></ul><p>第一种访问方式</p><p>--&gt; &lt;a href=&quot;${pageContext.request.contextPath}/account/findAccount&quot;&gt; 查询账户</p><ul><li>&lt;/a&gt;</li><li>&lt;br/&gt;</li><li>&lt;!--</li></ul><p>第二种访问方式</p><ul><li>--&gt;</li><li>&lt;a href=&quot;account/findAccount&quot;&gt;</li></ul><p>查询账户</p><ul><li>&lt;/a&gt;</li><li>&lt;/body&gt;</li><li>&lt;/html&gt;</li></ul><p><strong>注意：</strong><strong>当我们使用此种方式配置时，在</strong></p><p><code>jsp</code></p><p><strong>中第二种写法时，不要在访问</strong> <code>URL</code> <strong>前面加</strong><code>/</code><strong>，否则无法找到资源。</strong></p><p><code>method</code> <strong>属性的示例：</strong><strong>控制器代码：</strong></p><p>/** * 保存账户</p><ul><li>@return */ @RequestMapping(value=&quot;/saveAccount&quot;,method=RequestMethod.POST) public String saveAccount() { System.out.println(&quot; 保存了账户</li></ul><p>&quot;); return &quot;success&quot;; } ￼ jsp 代码： <code>\\&lt;!--</code> 请求方式的示例</p><ul><li>--&gt;</li><li>&lt;a href=&quot;account/saveAccount&quot;&gt;</li></ul><p>保存账户，<code>get</code> 请求</p><p>&lt;/a&gt; &lt;br/&gt; &lt;form action=&quot;account/saveAccount&quot; method=&quot;post&quot;&gt; &lt;input type=&quot;submit&quot; value=&quot; <em>保存账户，</em><code>post</code> <em>请求</em></p><ul><li>&quot;&gt;</li><li>&lt;/form&gt;</li></ul><p><strong>注意：</strong> 当使用</p><p><code>get</code></p><p>请求时，提示错误信息是 <code>405</code>，信息是方法不支持 <code>get</code> 方式请求</p><p><code>params</code> <strong>属性的示例：</strong><strong>控制器的代码：</strong></p><p>/** * 删除账户</p><ul><li>@return */ @RequestMapping(value=&quot;/removeAccount&quot;,params= {&quot;accountName&quot;,&quot;money&gt;100&quot;}) public String removeAccount() { System.out.println(&quot; 删除了账户</li></ul><p>&quot;); return &quot;success&quot;; } jsp <strong>中的代码：</strong></p><p><code>\\&lt;!--</code></p><p>请求参数的示例</p><p>--&gt; &lt;a href=&quot;account/removeAccount?accountName=aaa&amp;money&gt;100&quot;&gt; 删除账户，金额</p><p>100&lt;/a&gt; &lt;br/&gt; &lt;a href=&quot;account/removeAccount?accountName=aaa&amp;money&gt;150&quot;&gt; 删除账户，金额</p><p><code>150\\&lt;/a\\&gt;</code><strong>注意：</strong> 当我们点击第一个超链接时<code>,</code>可以访问成功。 当我们点击第二个超链接时，无法访问。如下图：</p></div>',1)])])}const m=t(n,[["render",a]]);export{u as __pageData,m as default};
